pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 changeFee) public {
        // The changeFee parameter is supplied by the fuzzer.
        // We initialize the contract with the given changeFee.
        c.initialize(
            address(0),                    // _baseToken (ETH)
            address(0),                    // _nft
            100,                           // _virtualBaseTokenReserves
            100,                           // _virtualNftReserves
            changeFee,                     // _changeFee
            100,                           // _feeRate
            bytes32(0),                    // _merkleRoot
            false,                         // _useStolenNftOracle
            false                          // _payRoyalties
        );

        // The general rule: the stored changeFee MUST equal the supplied changeFee.
        // The reference contract stores it; the mutant omits the assignment, so changeFee stays 0.
        assertTrue(c.changeFee() == changeFee);
    }
}

